using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Task<CapturedRequest> captured;
    private Func<(int Status, string Body)> reply = () => (200, """{"status":"approved"}""");

    public HttpPaymentGatewayTests()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        var prefix = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(prefix);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(prefix) };
        captured = ServeOnce();
    }

    private async Task<CapturedRequest> ServeOnce()
    {
        var context = await listener.GetContextAsync();
        using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
        var body = await reader.ReadToEndAsync();
        var result = new CapturedRequest(
            context.Request.HttpMethod,
            context.Request.Url!.AbsolutePath,
            context.Request.ContentType,
            body);

        var (status, responseBody) = reply();
        var bytes = Encoding.UTF8.GetBytes(responseBody);
        context.Response.StatusCode = status;
        context.Response.ContentType = "application/json";
        context.Response.ContentLength64 = bytes.Length;
        await context.Response.OutputStream.WriteAsync(bytes);
        context.Response.Close();
        return result;
    }

    private Task<AuthorizationOutcome> Authorize(string reference = "ORD-1", decimal amount = 12.5m, string currency = "eur") =>
        new HttpPaymentGateway(client).AuthorizeAsync(reference, new Money(amount, currency), CancellationToken.None);

    [Fact]
    public async Task Sends_a_json_POST_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        await Authorize("ORD-42", 12.5m, "eur");

        var request = await captured;
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);

        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-42", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        reply = () => (200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        reply = () => (200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        reply = () => (200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_not_an_error()
    {
        reply = () => (402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("""{}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""null""")]
    public async Task An_answer_that_is_not_an_explicit_approval_is_never_treated_as_approved(string body)
    {
        reply = () => (200, body);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_malformed_answer_fails_loudly()
    {
        reply = () => (200, "<html>oops</html>");

        await Assert.ThrowsAsync<JsonException>(() => Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_surface_as_errors_instead_of_decisions(int status)
    {
        reply = () => (status, """{"status":"approved"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize());
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }

    private sealed record CapturedRequest(string Method, string Path, string? ContentType, string Body);
}
